import express from 'express';
import cors from 'cors';
import path from 'path';
import { config } from './config/index.js';
import { router as apiRouter } from './api/routes.js';
import { memoryService } from './memory/memoryService.js';

const app = express();

// Middleware
app.use(cors({
  origin: '*',
  methods: ['GET', 'POST', 'DELETE', 'OPTIONS']
}));
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ extended: true }));

// Serve static audio files generated by TTS
app.use('/audio', express.static(config.audioDir));

// Mount API routes
app.use('/', apiRouter);

// Global 404 handler for unknown routes
app.use((req, res) => {
  res.status(404).json({
    error: {
      code: 'BAD_REQUEST',
      message: `Cannot ${req.method} ${req.url}`,
      retryable: false
    }
  });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('[Server Error]', err);
  res.status(500).json({
    error: {
      code: 'INTERNAL',
      message: err.message || 'Internal server error',
      retryable: false
    }
  });
});

const server = app.listen(config.port, config.host, async () => {
  console.log(`====================================================`);
  console.log(` Suzie Therapy Companion Backend running at:`);
  console.log(` http://${config.host}:${config.port}`);
  console.log(`====================================================`);
  
  // Stale-session recovery on startup per Section 7 Task 6
  await memoryService.recoverStaleSessions();
});

// Graceful shutdown
process.on('SIGINT', () => {
  console.log('\n[Server] Shutting down gracefully...');
  server.close(() => {
    console.log('[Server] Closed.');
    process.exit(0);
  });
});

process.on('SIGTERM', () => {
  console.log('\n[Server] SIGTERM received. Shutting down...');
  server.close(() => {
    console.log('[Server] Closed.');
    process.exit(0);
  });
});

export default app;
